  {
    "id": 53,
    "knowledge": "Recovery Trajectory Index (RTI)",
    "description": "Estimates the effectiveness of treatment adherence in achieving functional improvement at a facility.",
    "definition": "RTI = \\frac{\\sum_{i \\in treatmentoutcomes} (funcimpv\\_score_i)}{|treatmentoutcomes|} \\times TAR, \\text{where } funcimpv\\_score = \\begin{cases} 3 & \\text{if } funcimpv = Significant \\\\ 2 & \\text{if } funcimpv = Moderate \\\\ 1 & \\text{if } funcimpv = Minimal \\end{cases}"
