  {
    "id": 58,
    "knowledge": "Facility with Potential Engagement-Outcome Disconnect",
    "description": "Identifies facilities where high therapy engagement scores do not seem to translate into expected functional improvements or recovery progression.",
    "definition": "A facility where TES > 2.0 AND RTI < 0.8, \\text{indicating high Therapy Engagement Score (TES) but a low Recovery Trajectory Index (RTI).}"
